window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9d0f8642cbca31cc"]={"versions": [{"id": "FIG-9d0f8642cbca31cc", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Physikalisches Artefakt- und Paketierungsmodell (Container-Strukturdiagramm).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong> Definiert die hierarchische Schachtelung und Integritätssicherung eines <strong>Backend Packages</strong> im Kontext des Functional Clusters <strong>Update and Configuration Management (UCM)</strong> der AUTOSAR Adaptive Platform (AP). Es dient als distributionsfähiges Artefakt für Over-the-Air (OTA)- oder Werkstatt-Updates zur Ausbringung und Aktualisierung von <strong>Software Clustern (SWCL)</strong> auf einer Adaptive Machine.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schaubild gliedert sich in eine dreistufige Kompositionshierarchie:</p>\n<ol class=\"fig-list\">\n<li><strong>Backend Package (Outer Envelope):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Oberste Auslieferungseinheit, die den signierten Container und die zugehörige Signatur kapselt.</li>\n<li>Enthält:</li>\n<li><code>Signed container</code>: Gekapselte Nutzlast inklusive Clustermetadaten.</li>\n<li><code>Integrator Signature</code>: Kryptografische Signatur (asymmetrischer Digest, z. B. RSA/ECDSA) des Systemintegrators/OEMs, die den gesamten <code>Signed container</code> absichert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Signed container (Security & Metadata Boundary):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schützt die Authentizität und Manipulationssicherheit des Zielpakets.</li>\n<li>Enthält:</li>\n<li><code>SWCL Package manifest</code>: ARXML-Deskriptor auf Paketebene. Spezifiziert Ziel-SWCL-Identifikator, Software-Version, Pre-/Post-Installationsschritte, Abhängigkeiten zu anderen Software-Clustern, Lizenzdaten sowie kryptografische Prüfsummen der Nutzdaten.</li>\n<li><code>Software Package A</code> (Kardinalität $1..n$ möglich): Der installationsfähige Payload des Software Clusters.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Software Package A (Software Cluster Deployment Unit):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das eigentliche Software-Cluster-Archiv, zusammengesetzt aus:</li>\n<li><code>Executables</code>: ELF-Binärdateien der Adaptive Applications bzw. Plattform-Services.</li>\n<li><code>Data</code>: Statische, nicht-flüchtige Read-Only-Daten, Kalibrier- und Konfigurationsdateien.</li>\n<li><code>Manifests</code>: Formalisierte ARXML-Modelle der Applikationselemente, insbesondere <code>Execution Manifest</code> (Prozesskonfiguration, Resource-Limits, Determinismus) und <code>Service Instance Manifest</code> (Binding für SOME/IP bzw. IPC, E2E, IAM).</li>\n<li><code>SWCL Integration arxml</code>: Integrationsbeschreibungen, die das Mapping des Software Clusters auf die Machine-Konfiguration (Machine Manifest, Netzwerkinterfaces, Betriebssystemzuordnung) herstellen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obwohl statisch strukturiert, erzwingt die Container-Hierarchie folgenden deterministischen Ablauf im UCM-Verarbeitungspfad:</p>\n<ol class=\"fig-list\">\n<li><strong>Ingestion & Streaming:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Transfer des <code>Backend Package</code> über die UCM-Schnittstellen (<code>PackageManagement::TransferStart</code>, <code>TransferData</code>, <code>TransferExit</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kryptografische Verifikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor jeglicher Extraktion validiert UCM die <code>Integrator Signature</code> gegen den <code>Signed container</code> unter Nutzung der <code>ara::crypto</code>-Schnittstelle bzw. hardwaregestützter Keys (HSM/SecOC/PKI).</li>\n<li><em>Abbruchbedingung:</em> Ungültige Signatur führt zu sofortigem Rejekt (<code>kAuthenticationFailed</code>) ohne Parsen von Nutzdaten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Metadaten- & Abhängigkeitsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parsen des <code>SWCL Package manifest</code>. UCM prüft Cluster-Kompatibilität, Ziel-Hardware, Speicherplatzbedarf und Versionsinterdependenzen (<code>SoftwareClusterInactivityRequirement</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Extraktion & Staging (<code>ProcessSwPackage</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Entpacken von <code>Software Package A</code> in den Staging-Bereich (inaktive Partition bei A/B-Systemen oder versioniertes Dateisystemverzeichnis).</li>\n<li>Auswertung der <code>Manifests</code> und der <code>SWCL Integration arxml</code> zur Konfiguration des Execution Management (EM).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung & State-Wechsel (<code>Activate</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>State Management (SM) triggert den Umschaltprozess; EM beendet alte Instanzen, übernimmt die neuen Executables/Manifeste und startet den neuen Softwarestand.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Validierung & Rollback:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schlägt der Selbsttest nach Aktivierung fehl, erfolgt via <code>Rollback</code> bzw. <code>RevertProcessedSwPackages</code> der deterministische Rückfall auf den vorherigen konsistenten SWCL-Zustand.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Strikte Trennung von Paket- und Cluster-Manifest:</strong> Metadaten (<code>SWCL Package manifest</code>) müssen zwingend vor dem Entpacken des eigentlichen Payloads (<code>Software Package A</code>) durch UCM auslesbar sein, um Fehlallokationen von Flash-Speicher frühzeitig zu verhindern.</li>\n<li><strong>Relokation & Pfadkonsistenz:</strong> <code>Executables</code> und <code>Manifests</code> dürfen keine absoluten Dateisystempfade hart codieren. Pfadauflösungen müssen relativ zum installationsspezifischen Root-Verzeichnis des Software Clusters erfolgen, um duale Partitionierungs- und Update-Mechanismen zu gewährleisten.</li>\n<li><strong>Persistency-Regel (ara::per):</strong> Unter <code>Data</code> mitgelieferte Dateien sind strikt Read-Only. Dynamisch veränderbare Applikationsdaten, Nichtflüchtigkeitsspeicher und Schlüssel dürfen niemals Teil des Software-Pakets sein, sondern müssen über den Functional Cluster <em>Persistency</em> verwaltet werden.</li>\n<li><strong>Integrations-ARXML:</strong> Die <code>SWCL Integration arxml</code> bindet die Anwendung an die konkrete Zielmaschine. Applikationsentwickler liefern ausschließlich generische Manifeste; die finale Aggregation im Backend Package obliegt der Integrator-Rolle.</li>\n</ul>"}, {"id": "FIG-4357e8e66699158a", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Physikalisches Artefakt- und Paketierungsmodell (verschachteltes Container-Strukturdiagramm).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong> Definiert die hierarchische Schachtelung und zweistufige Integritätssicherung eines <strong>Backend Packages</strong> im Kontext des Functional Clusters <strong>Update and Configuration Management (UCM)</strong> der AUTOSAR Adaptive Platform. Das Paket dient als distributionsfähiges Übertragungsartefakt für Over-the-Air- und Werkstatt-Updates zur Installation und Aktualisierung von Software-Paketen (<code>Software Package A</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schaubild gliedert sich in eine mehrstufig verschachtelte Sicherheits- und Kompositionshierarchie:</p>\n<ol class=\"fig-list\">\n<li><strong>Backend Package:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Oberste Kapselungs- und Auslieferungseinheit.</li>\n<li>Enthält den äußeren <code>Signed container</code> sowie die zugehörige <code>Integrator Signature</code> zur Absicherung des Gesamtkontainers.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Äußerer Signed container:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schützt die Authentizität und Manipulationssicherheit des Paket-Verbunds.</li>\n<li>Enthält:</li>\n<li><code>Software Package manifest</code>: ARXML-Deskriptor auf übergeordneter Paketebene zur Spezifikation von Metadaten, Abhängigkeiten und Installationsanweisungen.</li>\n<li><code>Software Package A</code>: Die auszubringende Software-Paketeinheit.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Software Package A:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Umfasst einen eigenständigen, inneren <code>Signed container</code> sowie eine zugehörige <code>Signature</code> des Paket-Erstellers.</li>\n<li>Der innere <code>Signed container</code> kapselt:</li>\n<li>Den eigentlichen Applikations-Payload: <code>Executables</code> (ausführbare Binärdateien), <code>Data</code> (statische Daten, Konfigurationen) und <code>Manifests</code> (ARXML-Ausführungs- und Service-Beschreibungen).</li>\n<li><code>Software Package Manifest</code>: Den ARXML-Paketdeskriptor des Software-Pakets.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die zweistufige Container-Architektur erzwingt folgenden deterministischen Verifikations- und Verarbeitungsablauf im UCM:</p>\n<ol class=\"fig-list\">\n<li><strong>Übertragung:</strong> Empfang des <code>Backend Package</code> über die UCM-Paketmanagementschnittstellen.</li>\n<li><strong>Primäre Verifikation:</strong> Validierung der <code>Integrator Signature</code> gegen den äußeren <code>Signed container</code>. Schlägt diese Prüfung fehl, wird das gesamte Paket unverzüglich abgewiesen.</li>\n<li><strong>Metadatenprüfung:</strong> Parsen des äußeren <code>Software Package manifest</code> zur Validierung von Kompatibilität, Versionen und Systemvoraussetzungen.</li>\n<li><strong>Sekundäre Verifikation:</strong> Validierung der inneren <code>Signature</code> gegen den inneren <code>Signed container</code> von <code>Software Package A</code> zur Sicherstellung der Integrität des Ersteller-Payloads vor der Entpackung.</li>\n<li><strong>Extraktion & Bereitstellung:</strong> Entpacken von <code>Executables</code>, <code>Data</code>, <code>Manifests</code> sowie Auswertung des inneren <code>Software Package Manifest</code> für das Staging und Deployment auf der Zielmaschine.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Relevanz:</strong> Spezifiziert die verbindliche zweistufige Sicherheitsstruktur (End-to-End-Signatur des Paketerstellers plus Integrator-Signatur des Backend-Pakets) für das Update and Configuration Management (UCM). Beide Signaturprüfungen sind verbindliche Vorbedingungen für die Installation.</li>\n<li><strong>Entwickler-Hinweise:</strong> Pakete müssen sowohl auf Ebene des inneren Software-Pakets als auch auf Ebene des Backend-Containers kryptografisch signiert sein. Das UCM validiert die Signaturen kaskadierend von außen nach innen, bevor Artefakte in das Dateisystem übernommen werden.</li>\n</ul>"}, {"id": "FIG-0ae1686fb452bb33", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Physikalisches Artefakt- und Paketierungsmodell (verschachteltes Container-Strukturdiagramm).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong> Definiert die hierarchische Schachtelung und zweistufige Integritätssicherung eines <strong>Backend Packages</strong> im Kontext des Functional Clusters <strong>Update and Configuration Management (UCM)</strong> der AUTOSAR Adaptive Platform. Das Paket dient als distributionsfähiges Übertragungsartefakt für Over-the-Air- und Werkstatt-Updates zur Installation und Aktualisierung von Software-Paketen (<code>Software Package A</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schaubild gliedert sich in eine mehrstufig verschachtelte Sicherheits- und Kompositionshierarchie:</p>\n<ol class=\"fig-list\">\n<li><strong>Backend Package:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Oberste Kapselungs- und Auslieferungseinheit.</li>\n<li>Enthält den äußeren <code>Signed container</code> sowie ein zugehöriges <code>Authentication tag</code> zur Absicherung des Gesamtkontainers.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Äußerer Signed container:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schützt die Authentizität und Manipulationssicherheit des Paket-Verbunds.</li>\n<li>Enthält:</li>\n<li><code>Software Package manifest</code>: ARXML-Deskriptor auf übergeordneter Paketebene zur Spezifikation von Metadaten, Abhängigkeiten und Installationsanweisungen.</li>\n<li><code>Software Package A</code>: Die auszubringende Software-Paketeinheit.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Software Package A:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Umfasst einen eigenständigen, inneren <code>Signed container</code> sowie ein zugehöriges <code>Authentication tag</code> zur Verifikation des Paketinhalts.</li>\n<li>Der innere <code>Signed container</code> kapselt:</li>\n<li>Den Applikations-Payload: <code>Executables</code> (ausführbare Binärdateien), <code>Data</code> (statische Daten, Konfigurationen) und <code>manifests</code> (ARXML-Ausführungs- und Service-Beschreibungen).</li>\n<li><code>Software Package Manifest</code>: Den ARXML-Paketdeskriptor des Software-Pakets.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die zweistufige Container-Architektur erzwingt folgenden deterministischen Verifikations- und Verarbeitungsablauf im UCM:</p>\n<ol class=\"fig-list\">\n<li><strong>Übertragung:</strong> Empfang des <code>Backend Package</code> über die UCM-Paketmanagementschnittstellen.</li>\n<li><strong>Primäre Verifikation:</strong> Validierung des äußeren <code>Authentication tag</code> gegen den äußeren <code>Signed container</code>. Schlägt diese Prüfung fehl, wird das gesamte Paket unverzüglich abgewiesen.</li>\n<li><strong>Metadatenprüfung:</strong> Parsen des äußeren <code>Software Package manifest</code> zur Validierung von Kompatibilität, Versionen und Systemvoraussetzungen.</li>\n<li><strong>Sekundäre Verifikation:</strong> Validierung des inneren <code>Authentication tag</code> gegen den inneren <code>Signed container</code> von <code>Software Package A</code> zur Sicherstellung der Authentizität und Integrität vor der Entpackung.</li>\n<li><strong>Extraktion & Bereitstellung:</strong> Entpacken von <code>Executables</code>, <code>Data</code>, <code>manifests</code> sowie Auswertung des inneren <code>Software Package Manifest</code> für das Staging und Deployment auf der Zielmaschine.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Relevanz:</strong> Spezifiziert die verbindliche zweistufige Sicherheitsstruktur (End-to-End-Signatur des Paketerstellers plus Integrator-Signatur des Backend-Pakets) für das Update and Configuration Management (UCM). Beide Signaturprüfungen sind verbindliche Vorbedingungen für die Installation.</li>\n<li><strong>Entwickler-Hinweise:</strong> Pakete müssen sowohl auf Ebene des inneren Software-Pakets als auch auf Ebene des Backend-Containers kryptografisch signiert sein. Das UCM validiert die Signaturen kaskadierend von außen nach innen, bevor Artefakte in das Dateisystem übernommen werden.</li>\n</ul>"}], "trans": [{"from": "FIG-9d0f8642cbca31cc", "to": "FIG-4357e8e66699158a", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>Signed container</code> (innere Schachtelung): In <code>Software Package A</code> wurde ein eigener innerer <code>Signed container</code> eingefügt, der den Payload (<code>Executables</code>, <code>Data</code>, <code>Manifests</code>) und das <code>Software Package Manifest</code> umfasst.</li>\n<li><code>Signature</code>: Für den inneren <code>Signed container</code> innerhalb von <code>Software Package A</code> wurde eine kryptografische <code>Signature</code> hinzugefügt.</li>\n<li><code>Software Package Manifest</code>: Das bisherige <code>SWCL Integration arxml</code> innerhalb des Software-Pakets wurde durch <code>Software Package Manifest</code> ersetzt.</li>\n<li><code>Software Package manifest</code>: Das äußere <code>SWCL Package manifest</code> auf Ebene des äußeren <code>Signed container</code> wurde in <code>Software Package manifest</code> umbenannt.</li>\n</ul>"}, {"from": "FIG-4357e8e66699158a", "to": "FIG-0ae1686fb452bb33", "fr": "R19-03", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>Authentication tag</code>: Die Signaturelemente (<code>Integrator Signature</code> des äußeren Containers sowie <code>Signature</code> des inneren Containers) wurden einheitlich in <code>Authentication tag</code> umbenannt.</li>\n<li><code>manifests</code>: Die Beschriftung <code>Manifests</code> im Payload-Block wurde in Kleinbuchstaben zu <code>manifests</code> geändert.</li>\n</ul>"}]};
